pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 seed, uint8 warp) public {
        vm.warp(warp);
        // We need pot to be < FEE_AMOUNT+1 so that when a payout is triggered,
        // the reference succeeds (pot will be 0 after) but the mutant underflows.
        // To set this up, we call play() until pot is 0. We use the fuzzed seed
        // to decide how many initial plays to attempt (each requires 10 wei).
        // By default pot starts at 0, which already satisfies pot < FEE_AMOUNT+1.
        // We keep pot at 0, which means the next play() that wins will try to
        // transfer pot - FEE_AMOUNT = 0 - 1, which reverts in the mutant but
        // succeeds in the reference (transfer 0, pot becomes 0).
        // However, the reference requires at least one prior play to add 10 wei
        // so that pot is at least 10, otherwise the transfer of 0 succeeds anyway.
        // Actually, we need to trigger a win when pot is 0 in the mutant but
        // nonzero in the reference. The easiest scenario: call play() once (adds 10),
        // then call play() again; if the second wins, reference pot=10-1=9 transferred,
        // mutant pot=0-1 underflows. So we need exactly one prior play.
        // We'll use the fuzzer to give us an address with funds and call play once.
        address player = address(uint160(uint256(keccak256(abi.encode(seed, "player")))));
        vm.deal(player, 10 ether);
        vm.prank(player);
        c.play{value: 10}();

        // Now pot = 10 in reference, 0 in mutant.
        // Next call to play: if it wins, reference transfers pot-FEE_AMOUNT = 9,
        // mutant tries to transfer 0-1 = revert.
        // We let the fuzzer supply a different address to call play.
        address caller = address(uint160(uint256(keccak256(abi.encode(seed, "caller")))));
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        bool success = true;
        try c.play{value: 10}() {
            success = true;
        } catch {
            success = false;
        }
        // The reference always succeeds (no revert) for any admissible input (value==10).
        // The mutant will revert when the second call wins and pot is 0 (underflow).
        assertTrue(success);
    }
}

