pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playsBefore, uint256 targetPlay) public {
        // playsBefore: number of losing plays before a possible win (0 or more)
        // targetPlay: the play number that might win
        // Bound to a reasonable range to keep fuzzing practical
        playsBefore = bound(playsBefore, 0, 10);
        targetPlay = bound(targetPlay, 0, 10);
        // Ensure targetPlay > playsBefore so we can execute at least one winning attempt after losing plays
        vm.assume(targetPlay > playsBefore);

        address player = address(0xabcd);
        vm.deal(player, 1000 ether);

        // Execute losing plays (requires randomness to be 1)
        // Since we can't control randomness, we just make many plays and then check the invariant.
        // The fuzzer will explore different block contexts; some runs will see a win at the targetPlay.
        for (uint i = 0; i < playsBefore; i++) {
            vm.prank(player);
            c.play{value: 10}();
        }

        // Now perform the target play which might win or lose
        vm.prank(player);
        c.play{value: 10}();

        // If the target play won (random == 0), pot should be 0.
        // If it lost (random == 1), pot will be >0 (accumulated).
        // The reference invariant: pot is never 1 after ANY sequence of plays.
        // (In the reference, pot is either a multiple of 10 after losing plays, or 0 after a win.
        // It can never be exactly 1.)
        assertTrue(c.pot() != 1);
    }
}

