pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(0) && player != address(c));
        uint256 ticketAmount = 10;
        vm.deal(player, ticketAmount + 1 ether);

        // first play, may win or lose
        vm.prank(player);
        try c.play{value: ticketAmount}() {} catch {}

        uint256 potBefore = c.pot();
        if (potBefore == 0) {
            // nothing to test, pot already zero
            assertTrue(true);
            return;
        }

        // play again, hoping for a win to trigger the reset in correct version
        vm.deal(player, ticketAmount);
        vm.prank(player);
        try c.play{value: ticketAmount}() {} catch {}

        uint256 potAfter = c.pot();
        // After any play, if player won, pot must be 0. This always holds in reference.
        // We check: potAfter is 0 if random gave a win. But we cannot observe random.
        // The general property: after two consecutive plays, if potBefore > 0 and second play succeeds,
        // potAfter must be 0 in reference, but in buggy version potAfter may remain > 0.
        // So we assert potAfter == 0 when potBefore > 0 and call didn't revert.
        // However, the second play may also lose, making potAfter > potBefore; but in bug, if it wins, potAfter = potBefore - 1 != 0.
        // We need a property that holds in ref always. Ref: pot is only non-zero after a loss. After any win, pot is zero.
        // Property: If potBefore > 0 and second call does not revert, then potAfter == 0 (because the only way pot stays non-zero
        // in ref after a non-reverting call is if loss, which adds to pot. But a loss means potAfter = potBefore + ticketAmount.
        // That contradicts potAfter == 0. So potAfter == 0 is NOT always true after non-reverting call.
        // So we need a different property.
        // The key: in reference, pot can only be 0 or a multiple of ticketAmount (excluding the fee?). Actually pot increments by ticketAmount on each play, and resets to 0 on win.
        // After a win, pot is 0. M fails to set pot=0, so after a win pot remains non-zero.
        // We can detect this by checking: after a call that doesn't revert, if pot decreased, it must have decreased to exactly 0.
        // In ref, decrease only happens on win, to 0. In bug, decrease (transfer out pot-FEE) but pot not set to 0, so pot remains >0.
        // So property: if potAfter < potBefore, then potAfter == 0. In bug, after a win, potAfter = potBefore - (potBefore - FEE) = FEE? Wait calculation:
        // Reference win: transfers pot - FEE to player, FEE to bank, sets pot=0. Bug win: transfers pot - FEE to player, FEE to bank, does NOT set pot=0.
        // So pot not changed in bug after win. Actually pot received msg.value before, so pot += ticketAmount, then transfer doesn't subtract from pot. The pot stays at original value (including the added ticketAmount). So potAfter = potBefore + ticketAmount? No, potBefore already includes the previous plays.
        // Let's simulate: initial pot 0, first play wins: pot += 10 -> pot=10, win -> transfer 9 to player, 1 to bank, pot unchanged in bug => pot remains 10. In ref, pot=0.
        // Second play: pot += 10 -> pot=20, win -> transfer 19 to player, pot unchanged in bug => pot=20. So bug pot grows.
        // In ref, second play: pot before = 0, after win pot=0.
        // So property: after any play, pot is either 0 or at least ticketAmount. That's true in both.
        // We need a dynamic property that holds for ref always but fails for bug sometimes.
        // Consider: after a play, if pot > 0, then adding ticketAmount to the balance of the contract should be less than pot + something? No.
        // Better: in ref, address(c).balance == pot + something? Not simple.
        // Another property: in ref, pot <= address(c).balance. Actually pot tracks contributions, but FEE is taken out on win, and pot set to 0. On loss, pot = contributions, contract balance = contributions. So after loss, pot == address(c).balance. After win, pot=0 and address(c).balance=0. This holds for ref. In bug, after win, pot > 0 but address(c).balance = 0, so pot > address(c).balance. Thus property: pot <= address(c).balance. In ref always true, in bug after a win it's false (pot > 0 but balance = 0).
        // That's a great universal invariant: pot <= address(c).balance.
        // For ref: always true. For bug: after a win, pot > 0 and balance 0, so fails.
        // So the assertion is just: assertTrue(c.pot() <= address(c).balance);
        // We don't need to know if win/loss. Just fuzz player and multiple calls.
        // We'll allow multiple plays to increase chance of hitting win.

        assertTrue(c.pot() <= address(c).balance);
    }
}

