contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 plays, uint8 seed) public {
        // bound calls between 2 and 10 to ensure multiple plays
        uint256 count = bound(plays, 2, 10);
        address gambler = address(0x1234);
        uint256 initialPlayAmount = 10;
        for (uint256 i = 0; i < count; i++) {
            // ensure gambler always has enough ETH for a play
            vm.deal(gambler, initialPlayAmount * 2);
            vm.prank(gambler);
            try c.play{value: initialPlayAmount}() {
            } catch {
                // if a play reverts, we stop measuring
                return;
            }
            // warp and roll to get a new random outcome
            vm.warp(block.timestamp + 1 + (i * 2));
            vm.roll(block.number + 1);
        }

        // after the loop, give the gambler funds for one more play
        vm.deal(gambler, initialPlayAmount);
        vm.prank(gambler);
        bool ok = true;
        try c.play{value: initialPlayAmount}() {
            ok = true;
        } catch {
            ok = false;
        }
        // The property: the final play must always succeed.
        // In P, pot resets so the contract always has enough ETH for the transfer.
        // In M, pot can grow without reset, causing a transfer that exceeds balance and a revert.
        assertTrue(ok);
    }
