import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 numPlays) public {
        // Restrict to a reasonable number of plays to keep the domain wide but feasible.
        bound(numPlays, 1, 20);
        // Fund the initial actor generously.
        address actor = address(0x1000);
        uint256 ticketAmount = 10;
        vm.deal(actor, numPlays * ticketAmount);

        // Drive multiple play calls sequentially.
        vm.startPrank(actor);
        for (uint8 i = 0; i < numPlays; i++) {
            c.play{value: ticketAmount}();
        }
        vm.stopPrank();

        // Calculate total fees sent to bank = bank balance (bank never spends, it only receives).
        // Since bank starts with 0, total fees = bank balance.
        uint256 totalFeesSent = address(c.bank()).balance;
        // The invariant: contract ETH balance + total fees sent == pot.
        uint256 contractBalance = address(c).balance;
        uint256 pot = c.pot();
        assertTrue(contractBalance + totalFeesSent == pot, "Invariant: contract balance + fees sent must equal pot");
    }
}

