    constructor(C _c) { c = _c; }
    function run(uint ticketPayment) public payable {
        require(ticketPayment == 10);
        require(address(this).balance >= ticketPayment);
        c.play{value: ticketPayment}();
        assert(c.pot() != 0);
    }
